/** Offline reconciliation of one exact failed attempt. No network/database operations. */
import {readFile,writeFile} from 'node:fs/promises';
import {readM78ContinuationJournal} from '../../tools/staging/check-m78-continuation';
import {readM78Continuation3Diagnostics,M78_CONTINUATION3_INTERRUPTION,verifyM78Continuation3Disposition} from '../../tools/staging/check-m78-continuation3';
import {m78Continuation3SourcePins,M78_CONTINUATION3_EVIDENCE_PINS} from '../../tools/staging/m78-continuation3-source-pins';
import {m78CanonicalJson as canonical} from '../../packages/neuvetra-database/src/m78-validation';
import {verifyCI,DISPOSITION_PIN,verifyBaseline} from './m78-continuation3-baseline-independent-review';
const sha=(b:string|Uint8Array)=>new Bun.CryptoHasher('sha256').update(b).digest('hex'),check=(v:unknown,m:string)=>{if(!v)throw Error(m)},same=(a:unknown,b:unknown)=>canonical(a)===canonical(b);
const journalPath='.superpowers/m78-hosted-continuation3.jsonl',diagnosticPath='.superpowers/m78-hosted-continuation3-diagnostics.jsonl',gatePath='.superpowers/m78-continuation3-journey-gate.json';
const text=await readFile(journalPath,'utf8'),dt=await readFile(diagnosticPath,'utf8'),gb=await readFile(gatePath);
check(sha(text)==='0204a7e93849b305bafc45b79232b3af588619fcb851752d2ef541869d584012'&&sha(dt)==='8b45e72d193d9f3c2b6a03c63c75e61a8055223862f13b297c9b4d26725972c1'&&sha(gb)==='60250cc38cb8a7ec8a2bb1188ba5c41e6f3dd89a1d298f0a6874eeead05ce40f','Exact evidence bytes');
const company=JSON.parse(text.split('\n')[0]!).workspaceId,es=readM78ContinuationJournal(text,company),ds=readM78Continuation3Diagnostics(dt),gate=JSON.parse(gb.toString()),last=es.at(-1)!,end=ds.at(-1)!;
check(es.length===24&&last.sha256==='7dc4b514e0dbcf0d29c857d146f6db709d9317fdfd0dc69a6be50c19acb1cbfa'&&last.kind==='attempt_finished'&&last.data.status==='failed'&&last.data.requests===30&&last.data.applicationPostRequests===0&&last.data.unknownAuthSessions===0&&last.data.allCreatedAuthSessionsClosed===true,'Exact failed main closure');
check(es.every(e=>e.mode==='baseline'&&!e.kind.startsWith('post_')&&!['baseline','exercise_complete','revisit_verified','legacy_auth_intent','legacy_auth_outcome'].includes(e.kind)),'No baseline completion or application posts/legacy sessions');
for(const role of ['manager1','manager2','member','outsider'])check(es.filter(e=>e.kind==='auth_outcome'&&e.data.role===role&&e.data.status===200&&e.data.tokenObserved===true&&e.data.subjectMatched===true).length===1&&es.filter(e=>e.kind==='logout_outcome'&&e.data.role===role&&e.data.status===204).length===1,'Four exact session closures');
check(ds.length===62&&end.sha256==='0dc8e2b0b40fd10b183579a19748e117d6ec5d68c98a69d2fdfb6f4b25bb6f65'&&end.kind==='phase_finished'&&same(end.data,{status:'failed',paused:false,diagnosticsHealthy:true,applicationPostRequests:0,allCreatedAuthSessionsClosed:true}),'Exact diagnostic closure');
const first=ds[0]!;check(first.kind==='phase_started'&&first.data.journal===journalPath&&same(first.data.interruption,M78_CONTINUATION3_INTERRUPTION)&&same(first.data.disposition,DISPOSITION_PIN)&&first.data.failedBaselineSha256==='8525a8416b3e55f07d508c9a9ec17fc8ac0a4902e798534dc05e9f4df72d1a46'&&first.data.failedBaselineHead==='e766f74b730bebf69849945407598c011f918b9a77b7ff9c3a5913cd6964f744','Exact parents');
const requests=new Map<number,any>();let ordinal=0,time=0;for(const e of ds){const now=Date.parse(e.createdAt);check(e.mode==='baseline'&&Number.isFinite(now)&&now>=time,'Chronology');time=now;if(e.kind==='request_intent'){check(e.data.ordinal===++ordinal&&['GET','POST'].includes(e.data.method),'Request order');check(e.data.method!=='POST'||['auth:/auth/v1/token','auth:/auth/v1/logout'].includes(e.data.route),'No app POST');requests.set(ordinal,{...e.data,outcome:null});}else if(['response_headers','request_error'].includes(e.kind)){const r=requests.get(e.data.ordinal);check(r&&r.outcome===null&&e.data.elapsedMs>=0,'Unique paired outcome');r.outcome=e;}else check(e===first||e===end,'No extra events');}
check(requests.size===30&&[...requests.values()].every(r=>r.outcome!==null),'All requests paired');
const errors=ds.filter(e=>e.kind==='request_error'),target=requests.get(26);check(errors.length===1&&errors[0]!.data.ordinal===26&&errors[0]!.data.category==='timeout'&&errors[0]!.data.elapsedMs===30007&&target.method==='GET'&&target.route==='application:/workspace-api/workspace/:id/corporate-inventories/:id/versions/:id/coverage-export'&&last.data.stage.endsWith('/coverage-export'),'Single exact coverage export timeout');
for(const [route,status] of [['auth:/auth/v1/token',200],['auth:/auth/v1/logout',204]]as const){const rs=[...requests.values()].filter(r=>r.route===route);check(rs.length===4&&rs.every(r=>r.outcome.kind==='response_headers'&&r.outcome.data.status===status),'Diagnostic auth closure');}
check(Date.parse(first.createdAt)<=Date.parse(es[0]!.createdAt)&&Date.parse(end.createdAt)>=Date.parse(last.createdAt),'Phase brackets main');
for(const pin of Object.values(gate.artifacts) as {path:string;sha256:string}[])check(sha(await readFile(pin.path))===pin.sha256,'Gate artifact '+pin.path);
const pins=await m78Continuation3SourcePins(),receipt=JSON.parse(await readFile(gate.artifacts.independentReview.path,'utf8'));check(pins.length===166&&same(pins,gate.sourcePins)&&same(pins,receipt.sourcePins)&&same(receipt.evidencePins,M78_CONTINUATION3_EVIDENCE_PINS)&&M78_CONTINUATION3_EVIDENCE_PINS.length===6,'Source/evidence closure');for(const pin of M78_CONTINUATION3_EVIDENCE_PINS)check(sha(await readFile(pin.path))===pin.sha256,'Historical bytes');
check(same(gate.artifacts.interruptionDisposition,DISPOSITION_PIN),'Disposition binding');await verifyM78Continuation3Disposition({roster:{workspaceId:company},interruptionDisposition:DISPOSITION_PIN}as any,{read:async p=>{try{return await readFile(p,'utf8')}catch{return null}}});
const runtime=JSON.parse(await readFile(gate.artifacts.runtime.path,'utf8')),ci=JSON.parse(await readFile(gate.artifacts.ciChecks.path,'utf8')),commit='59cda7a62d8dcc6b554c92372e3b032577e410c9',toolingCommit='c37aa357fd0984be726ee0719226b58e4bfc5d61';verifyCI(ci,toolingCommit);check(gate.toolingCommit===toolingCommit&&gate.profile==='m78-root-continuation3-journey-gate-v1'&&gate.mode==='baseline'&&receipt.status==='m78_independent_continuation3_preparation_passed'&&same(es.find(e=>e.kind==='attempt_started')!.data.gate,gate.gate),'Outer admission');
check(runtime.status==='m78_runtime_verified'&&runtime.schemaVersion===21&&runtime.commit===commit&&runtime.deploymentId==='0f2e99f3-67ef-4f4c-b3c3-a39c62eabc78'&&runtime.imageDigest==='sha256:fe46a0e354252026f2bcbf6672e10ec550e52a56f064ab3e75a8af17625749c9'&&runtime.httpStatus===200,'Runtime');const age=Date.parse(es[1]!.createdAt)-Date.parse(runtime.observedAt);check(age>=0&&age<=900000,'Fresh runtime');const ready=es.find(e=>e.kind==='actual_readiness')!.data;check(ready.schemaVersion===21&&ready.applicationCommitAttestation===commit&&ready.sourceGate===gate.gate.independentReviewSha256&&ready.migrationSha256===gate.gate.migrationSha256,'Readiness');
let refused=false;try{await verifyBaseline(text,dt,{journalSha256:sha(text),journalHead:last.sha256}as any)}catch{refused=true}check(refused,'Success reviewer refuses actual failed attempt');
const result={status:'m78_independent_continuation3_baseline_failure_reconciled',reviewerId:'/root/resume_release',reviewedAt:new Date().toISOString(),journal:{path:journalPath,sha256:sha(text),head:last.sha256,events:24},diagnostics:{path:diagnosticPath,sha256:sha(dt),head:end.sha256,events:62},gate:{path:gatePath,sha256:sha(gb)},toolingCommit,applicationCommit:commit,schemaVersion:21,sourcePinCount:166,historicalEvidencePinCount:6,interruptionDisposition:DISPOSITION_PIN,requests:30,applicationPostRequests:0,knownSessions:4,logout204:4,unknownAuthSessions:0,allCreatedAuthSessionsClosed:true,legacySessionsCreated:0,timeout:{ordinal:26,method:'GET',route:target.route,elapsedMs:30007,responseHeadersObserved:false},completedAt:last.createdAt,baselineAccepted:false,completeRetainedBodyVerification:false,successReviewerRejected:true,providerCause:'not_established',networkUsed:false,databaseUsed:false,originalsModified:false};
const out='evaluations/research-qa/m78-continuation3-baseline-failure-result.json';await writeFile(out,JSON.stringify(result,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify({status:result.status,path:out,sha256:sha(await readFile(out))}));
